public long fib(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        long next = a + b;   // overflows a long past n = 92
        a = b;
        b = next;
    }
    return a;
}

