code.java:
import java.math.BigInteger;

public BigInteger fib(int n) {
    return fibPair(n)[0];
}

// returns {F(n), F(n+1)}
private BigInteger[] fibPair(int n) {
    if (n == 0) {
        return new BigInteger[]{BigInteger.ZERO, BigInteger.ONE};
    }
    BigInteger[] half = fibPair(n >> 1);
    BigInteger fk = half[0], fk1 = half[1];
    // F(2k) = F(k) * (2*F(k+1) - F(k))
    BigInteger c = fk.multiply(fk1.shiftLeft(1).subtract(fk));
    // F(2k+1) = F(k)^2 + F(k+1)^2
    BigInteger d = fk.multiply(fk).add(fk1.multiply(fk1));
    if ((n & 1) == 0) {
        return new BigInteger[]{c, d};        // even index
    } else {
        return new BigInteger[]{d, c.add(d)}; // odd index: shift by one
    }
}

