def fib(self, n: int) -> int:
    def fib_pair(k: int) -> tuple[int, int]:
        if k == 0:
            return (0, 1)
        fk, fk1 = fib_pair(k >> 1)
        c = fk * (2 * fk1 - fk)        # F(2k)
        d = fk * fk + fk1 * fk1        # F(2k+1)
        if k & 1:
            return (d, c + d)          # odd index: shift by one
        return (c, d)                  # even index
    return fib_pair(n)[0]

